<#
  Packs records.csv and topology.csv into bundle.js, which the portal's "Real"
  data source loads with a <script> tag (works over http(s) and from file://).
  Run after editing either CSV:   powershell -File data\real\build-bundle.ps1
#>
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
$enc = { param($name) ConvertTo-Json -InputObject ([System.IO.File]::ReadAllText((Join-Path $here $name))) -Compress }
$js = @(
  '// Generated by build-bundle.ps1 from records.csv and topology.csv in this folder. Do not edit by hand.'
  '// Desensitized Indianapolis DER data: coded circuit/substation names, noisy circuit locations,'
  '// installation coordinates removed. Loaded by the portal''s "Real" data source.'
  "window.HPCP_REAL_DATA = { records: $(& $enc 'records.csv'), topology: $(& $enc 'topology.csv') };"
) -join "`n"
[System.IO.File]::WriteAllText((Join-Path $here 'bundle.js'), $js + "`n")
"wrote bundle.js ($((Get-Item (Join-Path $here 'bundle.js')).Length) bytes)"
